// I2C wiring for Arduino Uno: A4=SDA, A5=SCL
#include 
#include 

LiquidCrystal_I2C lcd(0x27, 16, 2); // 0x27 is the common default address - use an I2C scanner if this doesn't work

void setup() {
 Wire.begin();
 lcd.init();
 lcd.backlight();
 lcd.print("Hello, Ekostra!");
}

void loop() {
 lcd.setCursor(0, 1);
 lcd.print(millis() / 1000);
 lcd.print(" sec");
 delay(500);
}",

